select 'stock' as entity,count(*) as n from stock union all select 'stock_candle',count(*) from stock_candle union all select 'scanner_detection',count(*) from scanner_detection union all select 'closing_recommendation_run',count(*) from closing_recommendation_run union all select 'closing_recommendation',count(*) from closing_recommendation union all select 'overnight_performance',count(*) from overnight_performance union all select 'overnight_position_decision',count(*) from overnight_position_decision union all select 'trade',count(*) from trade union all select 'market_broad_snapshot',count(*) from market_broad_snapshot union all select 'precision_subscription_session',count(*) from precision_subscription_session;
select execution_mode,strategy_version,count(*) as runs,min(recommendation_date),max(recommendation_date),count(*) filter(where request_key like 'official-%') official from closing_recommendation_run group by 1,2 order by 1,2;
select r.strategy_version,r.candidate_source,count(*) as n,min(r.recommendation_date),max(r.recommendation_date),min(recommendation_score),max(recommendation_score),count(distinct stock_id) stocks from closing_recommendation r group by 1,2;
select p.status,p.calculation_version,count(*) n,min(r.recommendation_date),max(r.recommendation_date),avg(close_return_rate),avg(max_return_rate),avg(max_drawdown_rate) from overnight_performance p join closing_recommendation r on r.id=p.closing_recommendation_id group by 1,2;
select timeframe,source,count(*) n,count(distinct stock_id) stocks,min(start_time),max(start_time),count(*) filter(where low<=0 or high<greatest(open,close) or low>least(open,close) or volume<0 or trading_value<0) bad_ohlcv from stock_candle group by 1,2;
select market_session_date,count(*) n,count(*) filter(where (detected_at at time zone 'Asia/Seoul')::time between time '14:30' and time '15:00') at_1500,count(*) filter(where received_at is null) no_receipt from scanner_detection group by 1 order by 1;
select id,recommendation_date,execution_mode,generated_at,evaluated_as_of,completed_at,request_key,settings_snapshot,left(response_snapshot,1000) snapshot_excerpt from closing_recommendation_run order by id desc limit 8;
select * from scanner_setting;
